{
  "title": "إنقاذ معابد أبو سمبل",
  "scenes": [
    {
      "title": "لغز الجبل",
      "narration": "إزاي نقدر ننقل معبد منحوت في قلب الجبل من مكانه الأصلي عشان نحميه من المية؟ ده كان السؤال الصعب اللي واجه المهندسين في جنوب مصر زمان.",
      "highlight": "لغز معبد",
      "visual_type": "temple",
      "labels": [
        "أبو سمبل"
      ],
      "source_ids": [
        "mota"
      ]
    },
    {
      "title": "بداية الحكاية",
      "narration": "المياه بدأت تعلى بسبب السد العالي، وكان لازم نتحرك بسرعة. بدأت عملية الإنقاذ الكبيرة في سنة ألف تسعمية أربعة وستين عشان نحافظ على تاريخنا العظيم من الغرق.",
      "highlight": "بدء الإنقاذ",
      "visual_type": "timeline",
      "labels": [
        "١٩٦٤"
      ],
      "source_ids": [
        "unesco_rescue"
      ]
    },
    {
      "title": "تعاون دولي",
      "narration": "مصر طلبت مساعدة اليونسكو، واتجمع خبراء من كل حتة في العالم. مهندسين وآثاريين اشتغلوا سوا عشان يلاقوا حل عملي، مش بس كلام، لإنقاذ المعابد دي من الضياع.",
      "highlight": "تعاون دولي",
      "visual_type": "network",
      "labels": [
        "اليونسكو"
      ],
      "source_ids": [
        "unesco_campaign"
      ]
    },
    {
      "title": "توثيق دقيق",
      "narration": "قبل ما نلمس أي حجر، كان لازم نوثق كل تفصيلة. كل جزء في المعبد اتصور واتسجل بدقة عشان نضمن إننا هنعرف نرجعه زي ما كان بالظبط بعد النقل.",
      "highlight": "توثيق وتصوير",
      "visual_type": "grid",
      "labels": [
        "توثيق"
      ],
      "source_ids": [
        "unesco_campaign"
      ]
    },
    {
      "title": "تقسيم المعابد",
      "narration": "بدأنا نقطع المعبد لكتل حجرية كبيرة ومدروسة. ده كان أصعب جزء، لإننا مش بس بنقطع صخر، إحنا بنتعامل مع تاريخ بيحكي قصة رمسيس التاني ونفرتاري في النوبة.",
      "highlight": "تقطيع الصخور",
      "visual_type": "cutaway",
      "labels": [
        "كتل حجرية"
      ],
      "source_ids": [
        "unesco_rescue"
      ]
    },
    {
      "title": "الرفع والنقل",
      "narration": "الكتل دي اتنقلت بحرص شديد عشان تطلع للمكان الجديد. العملية كانت محتاجة صبر وتخطيط، عشان نتفادى أي ضرر ممكن يحصل للأحجار القديمة دي أثناء الرفع والتحريك.",
      "highlight": "رفع الكتل",
      "visual_type": "crane",
      "labels": [
        "نقل"
      ],
      "source_ids": [
        "unesco_rescue"
      ]
    },
    {
      "title": "الموقع الجديد",
      "narration": "المكان الجديد كان مرتفع حوالي خمسة وستين متر عن المستوى القديم. ده خلانا نبعد المعابد عن خطر المية، ونحطها في أمان بعيد عن بحيرة ناصر اللي كانت بتهددها.",
      "highlight": "ارتفاع جديد",
      "visual_type": "distance",
      "labels": [
        "٦٥ متر"
      ],
      "source_ids": [
        "unesco_rescue"
      ]
    },
    {
      "title": "تراجع آمن",
      "narration": "مش بس الارتفاع، ده إحنا كمان بعدنا المعابد حوالي ميتين متر لجوه. المسافة دي كانت كافية عشان نضمن إن المية مش هتوصل للواجهة العظيمة بتاعة المعبد مرة تانية.",
      "highlight": "تراجع للداخل",
      "visual_type": "map",
      "labels": [
        "٢٠٠ متر"
      ],
      "source_ids": [
        "unesco_rescue"
      ]
    },
    {
      "title": "إعادة التجميع",
      "narration": "بعد ما نقلنا الكتل، بدأت مرحلة التجميع. المهندسين ركبوا الأجزاء تاني زي البازل، عشان يرجعوا شكل المعبد الأصلي اللي كان بيستقبل الشمس مرتين في السنة جوه الحرم.",
      "highlight": "تركيب دقيق",
      "visual_type": "assembly",
      "labels": [
        "تجميع"
      ],
      "source_ids": [
        "mota"
      ]
    },
    {
      "title": "جبل صناعي",
      "narration": "عشان المعبد يفضل شكله طبيعي، بنينا جبل صناعي حواليه. ده خلى الناس تحس إن المعبد لسه في مكانه الأصلي، مش مجرد حجارة محطوطة فوق بعضها في مكان جديد.",
      "highlight": "جبل صناعي",
      "visual_type": "blocks",
      "labels": [
        "هيكل"
      ],
      "source_ids": [
        "unesco_campaign"
      ]
    },
    {
      "title": "إتمام المهمة",
      "narration": "في سنة ألف تسعمية تمانية وستين، خلصت كل الأعمال وافتتحنا الموقع من جديد. كانت لحظة تاريخية أثبتت إننا نقدر نحمي تراثنا مع التطور اللي بيحصل في بلدنا.",
      "highlight": "افتتاح رسمي",
      "visual_type": "timeline",
      "labels": [
        "١٩٦٨"
      ],
      "source_ids": [
        "unesco_campaign"
      ]
    },
    {
      "title": "تراث عالمي",
      "narration": "العملية دي بقت نموذج للعالم كله في حماية التراث. اليونسكو اتعلمت مننا إزاي الدول ممكن تتعاون عشان تحمي كنوزها، وده اللي خلى التجربة دي علامة فارقة في التاريخ.",
      "highlight": "نموذج عالمي",
      "visual_type": "legacy",
      "labels": [
        "تراث"
      ],
      "source_ids": [
        "unesco_campaign"
      ]
    },
    {
      "title": "الواجهة العظيمة",
      "narration": "بص على التماثيل الضخمة دي، لسه واقفة بتشمخ في مكانها الجديد. رغم إن واحد منهم كان متضرر من زمان، لسه بيخطف عين أي حد يزوره في جنوب مصر.",
      "highlight": "تماثيل ضخمة",
      "visual_type": "temple",
      "labels": [
        "رمسيس"
      ],
      "source_ids": [
        "mota"
      ]
    },
    {
      "title": "معبد نفرتاري",
      "narration": "جنب المعبد الكبير، فيه المعبد الصغير الخاص بالملكة نفرتاري. هو كمان اتنقل بنفس الدقة، عشان يفضل شاهد على قصة حب وتقدير ملكي قديم، ومحدش ينسى جماله أبداً.",
      "highlight": "معبد نفرتاري",
      "visual_type": "temple",
      "labels": [
        "نفرتاري"
      ],
      "source_ids": [
        "mota"
      ]
    },
    {
      "title": "شمس أبو سمبل",
      "narration": "لحد النهاردة، الشمس بتدخل تنور قدس الأقداس مرتين في السنة. ده بيأكد إننا نجحنا في الحفاظ على أدق تفاصيل التصميم الهندسي اللي المصريين القدماء عملوه من آلاف السنين.",
      "highlight": "تعامد الشمس",
      "visual_type": "sun",
      "labels": [
        "ضوء"
      ],
      "source_ids": [
        "mota"
      ]
    },
    {
      "title": "رسالة للأجيال",
      "narration": "دي كانت قصة إرادة وتخطيط. أبو سمبل النهاردة مش مجرد معبد، ده رمز للي نقدر نعمله لما نشتغل سوا عشان نحمي تاريخنا ونبني مستقبلنا في نفس الوقت بكل فخر.",
      "highlight": "رمز الإرادة",
      "visual_type": "legacy",
      "labels": [
        "مصر"
      ],
      "source_ids": [
        "unesco_campaign"
      ]
    }
  ]
}
